scripts:
(() => {
  const plans = [
    { name: 'Starter', max: 2, year: 99, month: 12.99 },
    { name: 'Family', max: 4, year: 149, month: 19.99 },
    { name: 'Complete', max: 8, year: 199, month: 24.99 },
  ];
  const $ = (id) => document.getElementById(id);
  const money = (n) => '$' + n.toFixed(2).replace(/\.00$/, '');
  const billing = $('billing');
  let last = '';
  const calc = () => {
    const kids = +$('kids').value;
    const per = billing.dataset.value || 'year';
    $('kids-out').textContent = kids >= 9 ? '9+' : kids;
    const plan = plans.find((p) => kids <= p.max) || plans[2];
    const price = plan[per];
    const unit = per === 'year' ? '/year' : '/month';
    $('plan-name').textContent = plan.name;
    $('plan-why').textContent = `Up to ${plan.max} students`;
    $('r-price').textContent = money(price) + unit;
    $('r-child').textContent = money(price / Math.min(kids, plan.max)) + unit;
    $('plan-note').textContent = kids > 8
      ? 'More than 8 students: email OneHomeschool to ask about options.'
      : 'You can switch plans later if your family grows.';
    $('plan-cta').textContent = `See ${plan.name} on OneHomeschool ↗`;
    document.querySelectorAll('#plan-cards .plan-card').forEach((c) => c.classList.toggle('is-pick', c.dataset.plan === plan.name));
    if (plan.name !== last) { window.fgBump?.($('plan-name')); last = plan.name; }
  };
  $('kids').addEventListener('input', calc);
  billing.addEventListener('change', calc);
  $('copy-code').addEventListener('click', async () => {
    try { await navigator.clipboard.writeText('GIORGI2608'); $('copy-state').textContent = 'Copied ✓'; }
    catch { $('copy-state').textContent = 'Select & copy'; }
    window.trackAffiliateEvent?.('affiliate_code_copy', { affiliate_program: 'onehomeschool' });
    setTimeout(() => { $('copy-state').textContent = 'Copy'; }, 2200);
  });
  calc();
})();
